# GENERATE SQL FILE
# ============================================================

out_dir = r'C:\Users\kpand\Music\flawlex mastery\flawlex-mastery\supabase\seed'
out_file = os.path.join(out_dir, 'sbc_b9_questions.sql')

with open(out_file, 'w', encoding='utf-8') as f:
    f.write('-- Flawlex Mastery - SBC B9/JHS3 Questions\n')
    f.write(f'-- {len(T)} topics x 20 questions = {len(T) * 20} questions total\n')
    f.write('-- Generated from NaCCA CCP Science Curriculum (September 2020)\n\n')
    
    for topic_code, questions in T.items():
        f.write(f'-- ============================================================\n')
        f.write(f'-- {topic_code}\n')
        f.write(f'-- ============================================================\n\n')
        
        for i, qdata in enumerate(questions):
            qid = uid(topic_code, i)
            qtype = 'fill_in_blank' if qdata['type'] == 'fill' else 'multiple_choice'
            
            if qdata['type'] == 'mcq':
                opts_json = esc(json.dumps(qdata['opts']))
                answer_json = json.dumps(qdata['ans'])
            else:
                opts_json = 'NULL'
                answer_json = qdata['ans']
            
            hints_arr = ', '.join(f"'{esc(h)}'" for h in qdata['hints'])
            
            f.write(f"INSERT INTO questions (id, topic_id, owner_teacher_id, question_type, stem, options, correct_answer, explanation, hints, difficulty, blooms_level, visibility)\n")
            f.write(f"VALUES (\n")
            f.write(f"    '{qid}',\n")
            f.write(f"    (SELECT id FROM topics WHERE code = '{topic_code}'), NULL, '{qtype}',\n")
            f.write(f"    '{esc(qdata['stem'])}',\n")
            if qdata['type'] == 'mcq':
                f.write(f"    '{opts_json}'::jsonb,\n")
            else:
                f.write(f"    NULL,\n")
            f.write(f"    '{answer_json}'::jsonb,\n")
            f.write(f"    '{esc(qdata['exp'])}',\n")
            f.write(f"    ARRAY[{hints_arr}],\n")
            f.write(f"    '{qdata['diff']}', '{qdata['bloom']}', 'shared'\n")
            f.write(f");\n\n")

total_questions = sum(len(qs) for qs in T.values())
print(f'Generated: {out_file}')
print(f'Topics: {len(T)}')
print(f'Total questions: {total_questions}')
